import{c as t,Q as a,j as n,m as o}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"How to Build Claude Subagents Better Than 99% of People","description":"","frontmatter":{"url":"https://x.com/Jeyxbt/status/2067640206581190930","title":"How to Build Claude Subagents Better Than 99% of People","author":"Jeyxbt","archived":"2026-06-20T00:00:00.000Z","handle":"@Jeyxbt","published":"2026-06-18T00:00:00.000Z","stats":"238 likes · 32 retweets · 456 bookmarks · 30372 views","tags":["sub-agents","agent-design","claude-code","fleet-economics","context-management","tool-permissions"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-06-18-@Jeyxbt-190930.md","filePath":"research/tweets/2026-06-18-@Jeyxbt-190930.md","lastUpdated":1785909234000}'),s={name:"research/tweets/2026-06-18-@Jeyxbt-190930.md"};function i(r,e,l,h,d,u){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="how-to-build-claude-subagents-better-than-99-of-people-—-jeyxbt" tabindex="-1">How to Build Claude Subagents Better Than 99% of People — @Jeyxbt <a class="header-anchor" href="#how-to-build-claude-subagents-better-than-99-of-people-—-jeyxbt" aria-label="Permalink to &quot;How to Build Claude Subagents Better Than 99% of People — @Jeyxbt&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/Jeyxbt/status/2067640206581190930" target="_blank" rel="noreferrer">https://x.com/Jeyxbt/status/2067640206581190930</a><strong>作者</strong>：Jeyxbt（@Jeyxbt） <strong>發布日期</strong>：2026-06-18 <strong>收錄日期</strong>：2026-06-20 <strong>類型</strong>：Twitter Article <strong>統計</strong>：238 likes · 32 retweets · 456 bookmarks · 30372 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><blockquote><p>One Claude talks to you. Five more can be working behind it, on five different jobs, and you never see a single one. Those five are sub-agents. A sub-agent is a second Claude the main chat hires for one job, runs in its own window, and never lets near your conversation. Its own context window. Its own model. Its own permissions. Running in parallel. It does the messy work somewhere else and hands back one clean answer. That gap is the whole game. Point five of them at the same draft. One reads it as a complete beginner. One as a software engineer. One as a business owner. One as a publisher. They run at the same time, in separate windows, each with its own lens, and the main chat just collects what comes back. Five full reviews off one prompt, and your context never fills up. The main chat is the orchestrator. It is the only thing that talks to you. Everything else is a worker it spins up and points at a job: go read these files, go research this, go roast this plan. The worker does the job in its own session and reports back. Sub-agents answer to the orchestrator, not to you, and not to each other. Here&#39;s the part almost nobody gets right. The win was never that Claude does more work. It is that the heavy work stops happening in the window you are sitting in.</p></blockquote><hr><h1 id="first-the-receipt-that-makes-the-rest-matter" tabindex="-1">First, the receipt that makes the rest matter <a class="header-anchor" href="#first-the-receipt-that-makes-the-rest-matter" aria-label="Permalink to &quot;First, the receipt that makes the rest matter&quot;">​</a></h1><p>A reviewer sub-agent in one real run burned 22.8K tokens reading a plan and tearing it apart. What came back to the main session was a few lines. The main context never saw the 22.8K. It saw the verdict. That is the mechanic. Your main window fills as you work, and the more it fills, the more polluted it gets, and the dumber the model runs for the rest of the chat. A sub-agent sidesteps that. It wakes with a clean window, does the heavy reading in its own session, and slides back only the part you needed. Here is the same job, both ways: WITHOUT a sub-agent Main session reads 300 pages → 22.8K+ tokens land in main context Context now polluted, the model gets dumber for the rest of the chat All of it runs on Opus pricing</p><p>WITH a sub-agent Haiku worker reads the 300 pages in an isolated window Returns 3 facts to the main session Main context stays clean. Opus stays sharp. Bill drops. Now put the economics on top: THE FLEET ECONOMICS</p><p>Main session (orchestrator) &gt; Opus &gt; talks to you, plans, decides Research sub-agent &gt; Haiku &gt; reads 300 pages, returns 3 facts Test-writer sub-agent &gt; Sonnet &gt; writes the suite, returns the diff Doc-writer sub-agent &gt; Haiku &gt; drafts the README, returns the file</p><h2 id="smart-boss-on-the-expensive-model-cheap-workers-on-the-cheap-ones-you-don-t-run-opus-to-read-a-300-page-report-and-pull-three-numbers-you-send-haiku-it-burns-its-own-context-returns-the-summary-and-opus-stays-sharp-for-the-calls-that-actually-need-it-the-win-was-never-claude-does-more-it-s-that-the-expensive-thinking-and-the-cheap-reading-stop-happening-in-the-same-window-圖-1-—-來源-clean-vs-polluted-context" tabindex="-1">Smart boss on the expensive model. Cheap workers on the cheap ones. You don&#39;t run Opus to read a 300-page report and pull three numbers. You send Haiku. It burns its own context, returns the summary, and Opus stays sharp for the calls that actually need it. The win was never &quot;Claude does more.&quot; It&#39;s that the expensive thinking and the cheap reading stop happening in the same window. [圖 1 — 來源: clean vs polluted context] <a class="header-anchor" href="#smart-boss-on-the-expensive-model-cheap-workers-on-the-cheap-ones-you-don-t-run-opus-to-read-a-300-page-report-and-pull-three-numbers-you-send-haiku-it-burns-its-own-context-returns-the-summary-and-opus-stays-sharp-for-the-calls-that-actually-need-it-the-win-was-never-claude-does-more-it-s-that-the-expensive-thinking-and-the-cheap-reading-stop-happening-in-the-same-window-圖-1-—-來源-clean-vs-polluted-context" aria-label="Permalink to &quot;Smart boss on the expensive model. Cheap workers on the cheap ones.
You don&#39;t run Opus to read a 300-page report and pull three numbers. You send Haiku. It burns its own context, returns the summary, and Opus stays sharp for the calls that actually need it. The win was never &quot;Claude does more.&quot; It&#39;s that the expensive thinking and the cheap reading stop happening in the same window.
[圖 1 — 來源: clean vs polluted context]&quot;">​</a></h2><h1 id="built-in-agents-custom-agents-and-the-one-file-between-them" tabindex="-1">Built-in agents, custom agents, and the one file between them <a class="header-anchor" href="#built-in-agents-custom-agents-and-the-one-file-between-them" aria-label="Permalink to &quot;Built-in agents, custom agents, and the one file between them&quot;">​</a></h1><p>Those five personas were not custom anything. They were the built-in general-purpose agent, prompted five different ways. Claude ships with built-in agents. A research one fires on its own when you ask it to dig through a codebase or pull facts off the web. For a one-off, that is the right tool, and you&#39;ve probably watched it kick in without asking. A custom sub-agent is something you write. And it is smaller than people expect: a single Markdown file with YAML front matter, sitting in .claude/agents/. Structurally it is almost the same object as a skill file. The only real differences are the clean context window, the parallel run, and the model it sits on. Here is the whole thing:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: plan-roaster</span></span>
<span class="line"><span>description: Use proactively to stress-test any plan or design doc before</span></span>
<span class="line"><span>  implementation. Reads the plan, hunts for the weakest assumption, returns</span></span>
<span class="line"><span>  a short verdict. Use when a plan looks finished and you want an unbiased</span></span>
<span class="line"><span>  second pass.</span></span>
<span class="line"><span>tools: Read, Grep, Glob   # no Write, no Edit, no Bash — read-only is enforced, not requested</span></span>
<span class="line"><span>model: sonnet</span></span>
<span class="line"><span>color: orange</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>You are a cold, unbiased plan reviewer. You do not flatter.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Your job:</span></span>
<span class="line"><span>1. Read the plan the orchestrator hands you.</span></span>
<span class="line"><span>2. Name the single weakest assumption — the one that breaks the rest if it&#39;s wrong.</span></span>
<span class="line"><span>3. List 2-3 concrete failure modes, each in one line.</span></span>
<span class="line"><span>4. Return a 4-line verdict: the weak point, the failure modes, a fix, a score.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Rules:</span></span>
<span class="line"><span>- Read-only. You never edit files. You report.</span></span>
<span class="line"><span>- No praise padding. Lead with the problem.</span></span>
<span class="line"><span>- If the plan is solid, say so in one line and stop.</span></span></code></pre></div><h2 id="drop-that-in-claude-agents-and-claude-can-hand-plan-roasting-to-a-clean-context-reviewer-on-sonnet-the-file-is-doing-four-things-at-once-a-tight-role-a-fixed-output-shape-read-only-tools-a-chosen-model-every-line-is-a-lever-and-the-rest-of-this-is-about-pulling-them-right-圖-2-—-來源-the-file-anatomy" tabindex="-1">Drop that in .claude/agents/ and Claude can hand plan-roasting to a clean-context reviewer on Sonnet. The file is doing four things at once. A tight role. A fixed output shape. Read-only tools. A chosen model. Every line is a lever, and the rest of this is about pulling them right. [圖 2 — 來源: The File Anatomy] <a class="header-anchor" href="#drop-that-in-claude-agents-and-claude-can-hand-plan-roasting-to-a-clean-context-reviewer-on-sonnet-the-file-is-doing-four-things-at-once-a-tight-role-a-fixed-output-shape-read-only-tools-a-chosen-model-every-line-is-a-lever-and-the-rest-of-this-is-about-pulling-them-right-圖-2-—-來源-the-file-anatomy" aria-label="Permalink to &quot;Drop that in .claude/agents/ and Claude can hand plan-roasting to a clean-context reviewer on Sonnet. The file is doing four things at once. A tight role. A fixed output shape. Read-only tools. A chosen model. Every line is a lever, and the rest of this is about pulling them right.
[圖 2 — 來源: The File Anatomy]&quot;">​</a></h2><h1 id="the-levers-nobody-tells-you" tabindex="-1">The levers nobody tells you <a class="header-anchor" href="#the-levers-nobody-tells-you" aria-label="Permalink to &quot;The levers nobody tells you&quot;">​</a></h1><h2 id="_1-the-description-is-the-trigger-tune-it-like-it-s-the-only-thing-that-matters" tabindex="-1">1. The description is the trigger. Tune it like it&#39;s the only thing that matters. <a class="header-anchor" href="#_1-the-description-is-the-trigger-tune-it-like-it-s-the-only-thing-that-matters" aria-label="Permalink to &quot;1. The description is the trigger. Tune it like it&#39;s the only thing that matters.&quot;">​</a></h2><p>When Claude decides whether to fire a sub-agent, it reads the front matter and nothing else. The name and the description. Not the body. That is progressive disclosure: it skims the resume, and only pulls the full file in when the resume fits the job. So the description is the agent. A vague one fires when you don&#39;t want it and stays quiet when you do. Tighten it until the trigger is unambiguous, then test it in the wild. When it misbehaves, ask the one question that fixes it. Why didn&#39;t it fire? Then sharpen.</p><h2 id="_2-keep-the-description-short-a-bloated-trigger-taxes-every-decision" tabindex="-1">2. Keep the description short. A bloated trigger taxes every decision. <a class="header-anchor" href="#_2-keep-the-description-short-a-bloated-trigger-taxes-every-decision" aria-label="Permalink to &quot;2. Keep the description short. A bloated trigger taxes every decision.&quot;">​</a></h2><p>The &quot;generate with Claude&quot; option hands you a description three sizes too big. Trim it hard. The front matter gets read on every routing decision, so a fat description is a tax Claude pays again and again, not once. This is the rare place where less writing is literally faster. [圖 3 — 來源: progressive disclosure]</p><h2 id="_3-close-your-quotes-an-open-quote-in-the-yaml-kills-the-trigger-silently" tabindex="-1">3. Close your quotes. An open quote in the YAML kills the trigger silently. <a class="header-anchor" href="#_3-close-your-quotes-an-open-quote-in-the-yaml-kills-the-trigger-silently" aria-label="Permalink to &quot;3. Close your quotes. An open quote in the YAML kills the trigger silently.&quot;">​</a></h2><p>This one cost real time. A single unclosed quote in the front matter, and the trigger quietly stops working. There is no error and no warning. It simply never fires. The fix wasn&#39;t judgment or clever prompting. It was mechanical: close the quote. Before you debug your &quot;broken&quot; agent&#39;s logic, check the front matter is even valid. The gotcha is almost always a stray character, not your reasoning.</p><h2 id="_4-enforce-read-only-at-the-tool-layer-asking-nicely-is-not-a-permission-system" tabindex="-1">4. Enforce read-only at the tool layer. Asking nicely is not a permission system. <a class="header-anchor" href="#_4-enforce-read-only-at-the-tool-layer-asking-nicely-is-not-a-permission-system" aria-label="Permalink to &quot;4. Enforce read-only at the tool layer. Asking nicely is not a permission system.&quot;">​</a></h2><p>Most people write &quot;please don&#39;t modify any files&quot; in the prompt and think they built a read-only agent. They built a suggestion. Real safety lives in the tools field. List only Read, Grep, Glob, or explicitly drop the write tools, and the agent physically cannot touch your data. The mindset that separates the good ones: if your AI can touch data, assume it will. Build the wall, don&#39;t ask politely.</p><h2 id="_5-run-a-read-only-verifier-over-any-agent-file-you-didn-t-write" tabindex="-1">5. Run a read-only verifier over any agent file you didn&#39;t write. <a class="header-anchor" href="#_5-run-a-read-only-verifier-over-any-agent-file-you-didn-t-write" aria-label="Permalink to &quot;5. Run a read-only verifier over any agent file you didn&#39;t write.&quot;">​</a></h2><p>Because a sub-agent is just Markdown, you can download ones other people built. API designers, backend specialists, SQL experts, a whole library of them. You can also download a prompt injection. A malicious agent file is only text that tells Claude to do something it shouldn&#39;t. So point a read-only verifier at any file you didn&#39;t write and have it scan for injection or anything trying to escalate past its stated job. Vet the Markdown before it joins the fleet.</p><h2 id="_6-cap-the-loop-with-max-turns-before-it-eats-your-session" tabindex="-1">6. Cap the loop with max_turns before it eats your session. <a class="header-anchor" href="#_6-cap-the-loop-with-max-turns-before-it-eats-your-session" aria-label="Permalink to &quot;6. Cap the loop with max_turns before it eats your session.&quot;">​</a></h2><p>A sub-agent can get stuck circling. Re-reading, re-trying, never landing. Set max_turns and it stops after that many exchanges and reports what it has. Cheap insurance that turns a runaway into a bounded task.</p><h2 id="_7-match-the-model-to-the-task-don-t-run-opus-to-fetch-three-facts" tabindex="-1">7. Match the model to the task. Don&#39;t run Opus to fetch three facts. <a class="header-anchor" href="#_7-match-the-model-to-the-task-don-t-run-opus-to-fetch-three-facts" aria-label="Permalink to &quot;7. Match the model to the task. Don&#39;t run Opus to fetch three facts.&quot;">​</a></h2><p>The default move is to run the best model on everything. That is how you set money on fire. The orchestrator runs Opus because it plans and decides. The research worker runs Haiku because it reads and summarizes. Model is a per-agent field. Set it on purpose, and only let a worker inherit the parent&#39;s model when the job genuinely needs that much horsepower. Smart boss, cheap workers. Hand a 300-page read to Haiku and get back the three numbers you actually wanted.</p><h2 id="_8-pick-your-invocation-path-on-purpose" tabindex="-1">8. Pick your invocation path on purpose. <a class="header-anchor" href="#_8-pick-your-invocation-path-on-purpose" aria-label="Permalink to &quot;8. Pick your invocation path on purpose.&quot;">​</a></h2><p>There are four ways a sub-agent fires, and most people know one.</p><blockquote><p>Automatic. Claude reads the description and decides. Proactive. Put &quot;use proactively&quot; in the description and it jumps in without being asked. Explicit. Name it: &quot;use the plan-roaster sub-agent.&quot; Direct launch. Start a session as that sub-agent straight from the CLI. Proactive is the one people miss. It is how you get a reviewer that shows up every time a plan looks done, instead of waiting for you to remember it exists.</p></blockquote><h2 id="_9-project-level-for-the-repo-global-for-you-moving-between-them-is-a-copy-paste" tabindex="-1">9. Project-level for the repo. Global for you. Moving between them is a copy-paste. <a class="header-anchor" href="#_9-project-level-for-the-repo-global-for-you-moving-between-them-is-a-copy-paste" aria-label="Permalink to &quot;9. Project-level for the repo. Global for you. Moving between them is a copy-paste.&quot;">​</a></h2><p>Project agents live in the repo&#39;s .claude/agents/ and ship with the code, so anyone who clones it gets them. Global agents live at the user level, follow you across every project, and stay private. Because it&#39;s just a Markdown file, promoting a personal agent to a shared one is moving a file. Build it global while you tune it, then drop it in the repo once it has earned a spot on the team.</p><h2 id="_10-skills-and-sub-agents-aren-t-competitors-they-compose" tabindex="-1">10. Skills and sub-agents aren&#39;t competitors. They compose. <a class="header-anchor" href="#_10-skills-and-sub-agents-aren-t-competitors-they-compose" aria-label="Permalink to &quot;10. Skills and sub-agents aren&#39;t competitors. They compose.&quot;">​</a></h2><p>People burn hours on &quot;should this be a skill or a sub-agent?&quot; Wrong question. A skill runs inside the main session. A sub-agent runs in a clean, isolated, parallel session on its own model. That is the only real difference, and it means they stack. Skills can call sub-agents. Sub-agents can call skills. Use a skill when the work belongs in the main thread. Use a sub-agent when you want the work out of it.</p><h2 id="_11-dynamic-workflows-can-spin-up-a-swarm-they-also-eat-sessions-alive" tabindex="-1">11. Dynamic workflows can spin up a swarm. They also eat sessions alive. <a class="header-anchor" href="#_11-dynamic-workflows-can-spin-up-a-swarm-they-also-eat-sessions-alive" aria-label="Permalink to &quot;11. Dynamic workflows can spin up a swarm. They also eat sessions alive.&quot;">​</a></h2><p>On the newest Claude, one orchestration can spin up sub-agents in parallel. 3 in one test. 40 in another. 210 in a single run. That is a fleet doing order-independent work all at once. The power has a bill attached: that many parallel sessions chew through your limits fast. The trigger word even got renamed from the generic &quot;workflow&quot; to a deliberate one so it wouldn&#39;t kick off by accident. Reach for the swarm when the parallelism is real, not as a reflex. [圖 4 — 來源: the swarm]</p><h2 id="_12-the-default-general-purpose-agent-is-fine-until-you-ve-done-the-job-twice" tabindex="-1">12. The default general-purpose agent is fine - until you&#39;ve done the job twice. <a class="header-anchor" href="#_12-the-default-general-purpose-agent-is-fine-until-you-ve-done-the-job-twice" aria-label="Permalink to &quot;12. The default general-purpose agent is fine - until you&#39;ve done the job twice.&quot;">​</a></h2><h2 id="there-s-no-shame-in-the-built-in-agent-the-five-persona-demo-everyone-passes-around-is-just-the-general-purpose-agent-wearing-five-hats-for-a-one-off-that-s-correct-the-line-to-cross-is-the-second-time-you-do-the-job-repetition-is-the-signal-a-narrow-specialist-you-reuse-beats-a-generic-agent-you-re-brief-every-single-time" tabindex="-1">There&#39;s no shame in the built-in agent. The five-persona demo everyone passes around is just the general-purpose agent wearing five hats. For a one-off, that&#39;s correct. The line to cross is the second time you do the job. Repetition is the signal. A narrow specialist you reuse beats a generic agent you re-brief every single time. <a class="header-anchor" href="#there-s-no-shame-in-the-built-in-agent-the-five-persona-demo-everyone-passes-around-is-just-the-general-purpose-agent-wearing-five-hats-for-a-one-off-that-s-correct-the-line-to-cross-is-the-second-time-you-do-the-job-repetition-is-the-signal-a-narrow-specialist-you-reuse-beats-a-generic-agent-you-re-brief-every-single-time" aria-label="Permalink to &quot;There&#39;s no shame in the built-in agent. The five-persona demo everyone passes around is just the general-purpose agent wearing five hats. For a one-off, that&#39;s correct.
The line to cross is the second time you do the job. Repetition is the signal. A narrow specialist you reuse beats a generic agent you re-brief every single time.&quot;">​</a></h2><h1 id="when-to-delegate-and-when-it-quietly-hurts-you" tabindex="-1">When to delegate, and when it quietly hurts you <a class="header-anchor" href="#when-to-delegate-and-when-it-quietly-hurts-you" aria-label="Permalink to &quot;When to delegate, and when it quietly hurts you&quot;">​</a></h1><p>This is where fleets fall apart. People force sub-agents onto work that&#39;s wrong for them, and the agents make everything slower and pricier. The clean line: delegate when the work is independent and either disposable or repeated. Keep it in the main session when the work is sequential, conversational, or needs you. One question covers most of it — is this about to dump a pile of output into my chat that I&#39;ll never read again? If yes, send it out.</p><table tabindex="0"><thead><tr><th>Delegate to a sub-agent when…</th><th>Keep it in the main session when…</th></tr></thead><tbody><tr><td>You&#39;re about to dump output you&#39;ll never reread</td><td>It&#39;s a quick one-off edit</td></tr><tr><td>You&#39;re about to read many files</td><td>Steps depend on each other (1 &gt; 2 &gt; 3 &gt; 4)</td></tr><tr><td>The job repeats - build a specialist for it</td><td>The agents would need to talk to each other</td></tr><tr><td>Work is independent and parallel (review 15 chapters at once)</td><td>The agent needs the whole conversation&#39;s context</td></tr><tr><td>You want an unbiased fresh-context reviewer (AI is a sycophant by default)</td><td>The agent needs to ask you a question</td></tr><tr><td>You want to save money (300-page read &gt; Haiku &gt; 3 facts)</td><td>The task is genuinely one linear chain</td></tr><tr><td>Two traps worth naming flat. Sub-agents can&#39;t talk to each other. Each one is one-to-one with the main session. If your work needs agents coordinating, that is agent-teams with a shared task list, a different and pricier tool. Don&#39;t fake it with siloed sub-agents.</td><td></td></tr><tr><td>And only the orchestrator talks to you. A sub-agent that needs to ask a clarifying question is stuck, because it can&#39;t reach you. If the task can&#39;t be fully specified up front, it belongs in the main thread.</td><td></td></tr><tr><td>[圖 5 — 來源: One-To-One, No cross-talk]</td><td></td></tr></tbody></table><hr><h1 id="the-reviewer-trick-that-pays-for-itself" tabindex="-1">The reviewer trick that pays for itself <a class="header-anchor" href="#the-reviewer-trick-that-pays-for-itself" aria-label="Permalink to &quot;The reviewer trick that pays for itself&quot;">​</a></h1><h2 id="here-s-the-one-nobody-leads-with-by-default-an-ai-is-a-sycophant-ask-the-same-session-that-helped-you-build-a-plan-whether-the-plan-is-good-and-it-leans-toward-yes-it-is-already-invested-a-fresh-context-reviewer-carries-none-of-that-it-never-watched-you-build-the-plan-so-it-has-nothing-to-defend-and-no-framing-to-protect-the-clean-context-is-the-objectivity-you-can-t-get-an-honest-second-opinion-from-the-session-that-wrote-the-first-one-that-s-why-the-plan-roaster-runs-read-only-with-one-job-find-the-weakest-assumption-and-say-it-cold-the-same-logic-scales-to-a-security-auditor-a-test-writer-a-docs-writer-a-database-specialist-each-one-a-narrow-silo-each-great-at-its-single-thing-each-blind-to-your-ego-about-the-rest-that-s-the-assembly-line" tabindex="-1">Here&#39;s the one nobody leads with. By default, an AI is a sycophant. Ask the same session that helped you build a plan whether the plan is good, and it leans toward yes. It is already invested. A fresh-context reviewer carries none of that. It never watched you build the plan, so it has nothing to defend and no framing to protect. The clean context is the objectivity. You can&#39;t get an honest second opinion from the session that wrote the first one. That&#39;s why the plan-roaster runs read-only with one job: find the weakest assumption and say it cold. The same logic scales to a security auditor, a test writer, a docs writer, a database specialist. Each one a narrow silo, each great at its single thing, each blind to your ego about the rest. That&#39;s the assembly line. <a class="header-anchor" href="#here-s-the-one-nobody-leads-with-by-default-an-ai-is-a-sycophant-ask-the-same-session-that-helped-you-build-a-plan-whether-the-plan-is-good-and-it-leans-toward-yes-it-is-already-invested-a-fresh-context-reviewer-carries-none-of-that-it-never-watched-you-build-the-plan-so-it-has-nothing-to-defend-and-no-framing-to-protect-the-clean-context-is-the-objectivity-you-can-t-get-an-honest-second-opinion-from-the-session-that-wrote-the-first-one-that-s-why-the-plan-roaster-runs-read-only-with-one-job-find-the-weakest-assumption-and-say-it-cold-the-same-logic-scales-to-a-security-auditor-a-test-writer-a-docs-writer-a-database-specialist-each-one-a-narrow-silo-each-great-at-its-single-thing-each-blind-to-your-ego-about-the-rest-that-s-the-assembly-line" aria-label="Permalink to &quot;Here&#39;s the one nobody leads with. By default, an AI is a sycophant. Ask the same session that helped you build a plan whether the plan is good, and it leans toward yes. It is already invested.
A fresh-context reviewer carries none of that. It never watched you build the plan, so it has nothing to defend and no framing to protect. The clean context is the objectivity. You can&#39;t get an honest second opinion from the session that wrote the first one.
That&#39;s why the plan-roaster runs read-only with one job: find the weakest assumption and say it cold. The same logic scales to a security auditor, a test writer, a docs writer, a database specialist. Each one a narrow silo, each great at its single thing, each blind to your ego about the rest. That&#39;s the assembly line.&quot;">​</a></h2><h1 id="the-shape-of-it" tabindex="-1">The shape of it <a class="header-anchor" href="#the-shape-of-it" aria-label="Permalink to &quot;The shape of it&quot;">​</a></h1><p>Stop picturing a sub-agent as a smarter Claude. Picture a clean room with one door, one worker, one job. The orchestrator holds the conversation and the context. The specialists do the heavy reading and the parallel grunt-work in their own rooms, on their own cheap models, and slide the answer back under the door. The people building these better than everyone else aren&#39;t writing cleverer prompts. They&#39;re drawing tighter job descriptions, walling off permissions at the tool layer, and letting one smart lead run a fleet of cheap, narrow workers. The bottleneck was never how smart the model is. It was how clearly you can divide the work.</p><p>Hope you found something useful.</p><ul><li>Jey</li></ul><p>FOLLOW FOR MORE AI PLAYBOOKS. [圖 6 — 來源: Claude Workflow]</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Sub-agent 的核心機制是「把 heavy work 移出主 context window」而非「讓 Claude 做更多事」；12 條 lever 涵蓋 YAML 觸發調教、工具層權限、model 對位、invocation path 四選一到動態 swarm 上限。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li><strong>核心機制 — 污染 vs 乾淨 context</strong>：主 session context 越滿越笨；sub-agent 在獨立 window 消化 22.8K tokens，回傳幾行摘要，主 context 永遠不看到原始噪音；「heavy work 離開主 window」= 真正的收益</li><li><strong>Fleet economics</strong>：Orchestrator（Opus，決策）+ Research worker（Haiku，讀 300 頁）+ Test-writer（Sonnet，寫測試）+ Doc-writer（Haiku，寫 README）——smart boss + cheap workers，模型費用按任務難度分層</li><li><strong>Custom agent = 一個 Markdown 檔案</strong>：<code>.claude/agents/</code> 內 YAML front matter（name/description/tools/model/color）+ prompt body；skills 與 sub-agent 唯一差異是「獨立 context window + 平行執行 + 自選 model」</li><li><strong>12 條 lever 關鍵選項</strong>：① description = 唯一觸發器（Claude 只讀 front matter）② description 要短（每次 routing 決策都需讀）③ YAML unclosed quote 靜默殺死觸發 ④ 工具層才是真正 read-only（prompt 裡說「不要改」= 建議，不是權限）⑤ 外部 agent 檔案需 verifier 掃 injection ⑥ max_turns 防 agent 死循環 ⑦ model 逐 agent 設定 ⑧ 四種 invocation（auto/proactive/explicit/direct CLI）⑨ project vs global scope = 移動 md 檔案 ⑩ skills + sub-agents 可組合 ⑪ dynamic swarm 消耗 session limit 要謹慎 ⑫ 重複任務才值得建專家 agent</li><li><strong>委派判斷清單</strong>：delegate 條件（獨立工作、不需再讀輸出、高頻重複、想要無偏見 reviewer）vs 留主 session 條件（步驟有依賴、agent 需對話、需要全對話 context）</li><li><strong>Sycophancy 破解</strong>：同一 session 建計劃再問同一 session「計劃好嗎」= 必偏向 yes；fresh-context reviewer = 沒有包袱 = 真正的第二意見</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>實際 run 數據：reviewer sub-agent 燃燒 22.8K tokens → 主 session 只收到幾行結論</li><li>Dynamic swarm 規模：3 / 40 / 210 parallel sub-agents 實測案例</li><li><code>.claude/agents/</code> YAML 必填欄位：<code>name</code> / <code>description</code> / <code>tools</code> / <code>model</code> / <code>color</code></li><li>plan-roaster 完整 YAML 模板（copy-paste ready）</li><li>四種 invocation path：Automatic / Proactive / Explicit / Direct CLI launch</li><li>Delegation decision table：6 vs 6 條件清單</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li><strong>「99% of People」標題過度誇張</strong>：12 lever 中多數（model matching、tools 限制、max_turns）是已知 best practice，新意集中在 progressive disclosure 機制和 sycophancy 破解框架</li><li><strong>Lever 3（YAML unclosed quote）是 bug fix 非設計原則</strong>：有實用性但放在「12 levers nobody tells you」略顯湊數</li><li><strong>Dynamic swarm 部分語焉不詳</strong>：「trigger word 被 renamed」指什麼沒有明說，讀者可能困惑</li><li><strong>Delegation table 實用但不完整</strong>：未討論 agent 失敗時的 triage 路徑（cf. freeman1266 文章）</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>9/10</td><td>plan-roaster YAML 模板可直接貼用；12 lever checklist、delegation table、four invocation paths 均可即時套用於 .claude/agents/ 設計</td></tr><tr><td>B. 創新性 (20%)</td><td>7/10</td><td>「污染 context vs 乾淨 window」機制框架清晰；sycophancy 作為 fresh-context reviewer 論據有新意；YAML progressive disclosure 解釋是本文最佳洞察</td></tr><tr><td>C. 證據品質 (20%)</td><td>7/10</td><td>22.8K token 案例具體；fleet 分工表格有實質內容；swarm 規模（3/40/210）可信但無獨立驗證</td></tr><tr><td>D. 技術深度 (15%)</td><td>7/10</td><td>YAML front matter 結構、工具層 vs prompt 層權限分析、invocation path 四分類均具技術深度</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>Fleet economics + delegation rules + tool-layer permission 原則通用於任何 multi-agent 設計，不限 Claude Code</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.75/10</strong></td><td>9×0.3+7×0.2+7×0.2+7×0.15+8×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：12 條 sub-agent 設計 lever + delegation 決策清單 + fleet economics 分層模型是設計原則 checklist，直接對應 workspace 中 <code>.claude/agents/</code> 建立規範，屬 Rule 類型。plan-roaster YAML 模板作為可複製參考。</p>`,65)])])}const g=t(s,[["render",i]]);export{p as __pageData,g as default};
